apply.po.ranking <- function (partial.order.str) 
{
    partial.order.str <- as.matrix(partial.order.str)
    n <- nrow(partial.order.str)
    alts <- paste0("a", seq_len(n))
    i_seq <- rev(seq_len(n))
    while (length(i_seq) > 0) {
        i <- i_seq[1]
        merged <- FALSE
        j_seq <- rev(seq_len(ncol(partial.order.str)))
        for (j in j_seq) {
            if (i != j && partial.order.str[i, j] == "I") {
                alts[j] <- paste(alts[j], alts[i], sep = "; ")
                partial.order.str <- partial.order.str[-i, , 
                  drop = FALSE]
                partial.order.str <- partial.order.str[, -i, 
                  drop = FALSE]
                alts <- alts[-i]
                merged <- TRUE
                break
            }
        }
        if (merged) {
            n <- nrow(partial.order.str)
            i_seq <- rev(seq_len(n))
        }
        else {
            i_seq <- i_seq[-1]
        }
    }
    n_new <- nrow(partial.order.str)
    partial.order.mat <- matrix(0, n_new, n_new)
    for (i in seq_len(n_new)) {
        for (j in seq_len(n_new)) {
            if (partial.order.str[i, j] == "P+") {
                partial.order.mat[i, j] <- 1
            }
        }
    }
    row_sum <- rowSums(partial.order.mat)
    idx_sorted <- order(row_sum, decreasing = FALSE)
    alts_rank <- alts[idx_sorted]
    if (sum(row_sum) != 0) {
        alts_rank <- rev(alts_rank)
    }
    rank_mat <- partial.order.mat
    for (i in seq_len(n_new)) {
        for (j in seq_len(n_new)) {
            if (rank_mat[i, j] == 1) {
                tmp <- rank_mat[i, ] - rank_mat[j, ]
                tmp[tmp < 0] <- 0
                tmp[tmp > 1] <- 1
                rank_mat[i, ] <- tmp
            }
        }
    }
    list(partial.order.str = partial.order.str, partial.order.mat = partial.order.mat, 
        alts = alts, alts_rank = alts_rank, rank = rank_mat)
}

apply.COPRAS <- function (mat, weights, beneficial.vector) 
{
    normalized.mat <- t(t(mat)/colSums(mat))
    normalized.mat <- t(weights * t(normalized.mat))
    S_pos <- rowSums(normalized.mat[, beneficial.vector])
    S_neg <- rowSums(normalized.mat[, -beneficial.vector])
    Q_i <- S_pos + (min(S_neg) * sum(S_neg))/(S_neg * sum(min(S_neg)/S_neg))
    U_i <- Q_i/max(Q_i)
    return(U_i)
}

apply.FAHP <- function (A) 
{
    mat.1 <- A
    mat.2 <- A
    mat.3 <- A
    mat.1[mat.1 > 1 & mat.1 < 9] <- mat.1[mat.1 > 1 & mat.1 < 
        9] - 1
    mat.1[mat.1 < 1] <- sapply(mat.1[mat.1 < 1], function(x) {
        A <- 1/x
        if (A >= 2 && A <= 8) {
            return(1/(A + 1))
        }
        else {
            return(x)
        }
    })
    mat.3[mat.3 > 1 & mat.3 < 9] <- mat.3[mat.3 > 1 & mat.3 < 
        9] + 1
    mat.3[mat.3 < 1] <- sapply(mat.3[mat.3 < 1], function(x) {
        A <- 1/x
        if (A >= 2 && A <= 8) {
            return(1/(A - 1))
        }
        else {
            return(x)
        }
    })
    r1 <- apply(mat.1, 1, prod)^(1/4)
    r2 <- apply(mat.2, 1, prod)^(1/4)
    r3 <- apply(mat.3, 1, prod)^(1/4)
    A_curly <- colSums(t(rbind(r1, r2, r3)))
    A_curly_recip <- rev(A_curly)^-1
    fuzzy.weights.df <- data.frame(first_fuzzy_weight = numeric(), 
        second_fuzzy_weight = numeric(), third_fuzzy_weight = numeric())
    for (i in 1:dim(A)[1]) {
        fuzzy.weights.df <- rbind(fuzzy.weights.df, c(r1[i], 
            r2[i], r3[i]) * A_curly_recip)
    }
    rownames(fuzzy.weights.df) <- colnames(A)
    return(rowMeans(fuzzy.weights.df))
}

apply.MARA <- function (mat, weights, beneficial.vector) 
{
    if (ncol(mat) != length(weights)) {
        stop("Number of weights must match the number of columns in 'mat'.")
    }
    criterion.type <- rep("min", ncol(mat))
    criterion.type[beneficial.vector] <- "max"
    X <- mat
    for (j in seq_len(ncol(X))) {
        if (criterion.type[j] == "max") {
            X[, j] <- X[, j]/max(X[, j])
        }
        else {
            X[, j] <- min(X[, j])/X[, j]
        }
    }
    X <- sweep(X, 2, weights, `*`)
    opt <- apply(X, 2, max)
    S_k <- 0
    S_L <- 0
    T_k <- rep(0, nrow(X))
    T_L <- rep(0, nrow(X))
    for (j in seq_len(ncol(X))) {
        if (criterion.type[j] == "max") {
            S_k <- S_k + opt[j]
            T_k <- T_k + X[, j]
        }
        else {
            S_L <- S_L + opt[j]
            T_L <- T_L + X[, j]
        }
    }
    f_opt <- (S_L - S_k)/2 + S_k
    f_i <- (T_L - T_k)/2 + T_k
    M <- f_opt - f_i
    return(M)
}

apply.MOORA <- function (mat, weights, beneficial.vector) 
{
    weighted.normalized.mat <- t(weights * (t(mat)/(sqrt(colSums(mat^2)))))
    if (length(beneficial.vector) > 1) {
        A <- rowSums(weighted.normalized.mat[, beneficial.vector])
    }
    else {
        A <- (weighted.normalized.mat[, beneficial.vector])
    }
    if ((ncol(mat) - length(beneficial.vector)) > 1) {
        B <- rowSums(weighted.normalized.mat[, -beneficial.vector])
    }
    else {
        B <- (weighted.normalized.mat[, -beneficial.vector])
    }
    result <- A - B
    return(result)
}

generate.SPOTIS.bounds <- function (matrix) 
{
    if (!is.matrix(matrix) && !is.data.frame(matrix)) {
        stop("The decision matrix must be a numeric matrix or data frame.")
    }
    bounds <- cbind(apply(matrix, 2, min), apply(matrix, 2, max))
    return(bounds)
}

apply.WISP <- function (mat, beneficial.vector, weights, simplified = FALSE) 
{
    weights <- weights/sum(weights)
    X <- as.matrix(mat)
    n <- nrow(X)
    m <- ncol(X)
    eps <- 1e-16
    best <- apply(X, 2, max) + eps
    for (j in seq_len(m)) {
        X[, j] <- (X[, j]/best[j]) * weights[j]
    }
    non_beneficial <- setdiff(seq_len(m), beneficial.vector)
    v_p <- numeric(n)
    v_m <- numeric(n)
    w_p <- rep(1, n)
    w_m <- rep(1, n)
    for (i in seq_len(n)) {
        for (j in beneficial.vector) {
            v_p[i] <- v_p[i] + X[i, j]
            w_p[i] <- w_p[i] * X[i, j]
        }
        for (j in non_beneficial) {
            v_m[i] <- v_m[i] + X[i, j]
            w_m[i] <- w_m[i] * X[i, j]
        }
    }
    u_wsd <- v_p - v_m
    u_wpd <- w_p - w_m
    has_beneficial <- (length(beneficial.vector) > 0)
    has_nonbeneficial <- (length(non_beneficial) > 0)
    if (has_beneficial && !has_nonbeneficial) {
        u_wsr <- v_p
        u_wpr <- w_p
    }
    else if (!has_beneficial && has_nonbeneficial) {
        u_wsr <- 1/(v_m + eps)
        u_wpr <- 1/(w_m + eps)
    }
    else {
        u_wsr <- v_p/(v_m + eps)
        u_wpr <- w_p/(w_m + eps)
    }
    normalize_01 <- function(vec) {
        (1 + vec)/(1 + max(vec))
    }
    n_wsd <- normalize_01(u_wsd)
    n_wpd <- normalize_01(u_wpd)
    n_wsr <- normalize_01(u_wsr)
    n_wpr <- normalize_01(u_wpr)
    if (!simplified) {
        u <- (n_wsd + n_wpd + n_wsr + n_wpr)/4
    }
    else {
        u <- (n_wsd + n_wpr)/2
    }
    return(u)
}

apply.BORDA <- function (mat, beneficial.vector) 
{
    mat <- as.matrix(mat)
    if (!all(beneficial.vector %in% seq_len(ncol(mat)))) {
        stop("All elements of 'beneficial.vector' must be valid column indices of 'mat'.")
    }
    X <- matrix(0, nrow = nrow(mat), ncol = ncol(mat))
    for (j in seq_len(ncol(mat))) {
        if (j %in% beneficial.vector) {
            X[, j] <- rank(-mat[, j], ties.method = "first")
        }
        else {
            X[, j] <- rank(mat[, j], ties.method = "first")
        }
    }
    total <- rowSums(X)
    return(total)
}

apply.RAFSI <- function (mat, weights, beneficial.vector, ideal = NULL, anti_ideal = NULL, 
    n_i = 1, n_k = 6) 
{
    X <- as.matrix(mat)
    n_crit <- ncol(X)
    coef <- matrix(0, nrow = 2, ncol = n_crit)
    best <- numeric(n_crit)
    worst <- numeric(n_crit)
    for (j in seq_len(n_crit)) {
        if (j %in% beneficial.vector) {
            if (is.null(ideal)) {
                best[j] <- max(X[, j]) * 2
            }
            else {
                best[j] <- ideal[j]
            }
            if (is.null(anti_ideal)) {
                worst[j] <- min(X[, j]) * 0.5
            }
            else {
                worst[j] <- anti_ideal[j]
            }
        }
        else {
            if (is.null(anti_ideal)) {
                best[j] <- min(X[, j]) * 0.5
            }
            else {
                best[j] <- anti_ideal[j]
            }
            if (is.null(ideal)) {
                worst[j] <- max(X[, j]) * 2
            }
            else {
                worst[j] <- ideal[j]
            }
        }
        coef[1, j] <- (n_k - n_i)/(best[j] - worst[j])
        coef[2, j] <- (best[j] * n_i - worst[j] * n_k)/(best[j] - 
            worst[j])
    }
    S <- sweep(X, 2, coef[1, ], FUN = "*") + matrix(rep(coef[2, 
        ], nrow(X)), nrow = nrow(X), byrow = TRUE)
    A <- mean(c(n_i, n_k))
    H <- 2/((n_i^-1) + (n_k^-1))
    for (j in seq_len(n_crit)) {
        if (j %in% beneficial.vector) {
            S[, j] <- S[, j]/(2 * A)
        }
        else {
            S[, j] <- H/(2 * S[, j])
        }
    }
    V <- rowSums(sweep(S, 2, weights, FUN = "*"))
    return(V)
}

apply.SPOTIS <- function (matrix, weights, types, bounds) 
{
    if (!is.matrix(matrix) && !is.data.frame(matrix)) {
        stop("The decision matrix must be a numeric matrix or data frame.")
    }
    if (!is.numeric(weights) || length(weights) != ncol(matrix) || 
        sum(weights) != 1) {
        stop("Weights must be a numeric vector of length equal to the number of criteria, with a sum of 1.")
    }
    if (!is.numeric(types) || length(types) != ncol(matrix) || 
        !all(types %in% c(1, -1))) {
        stop("Types must be a numeric vector of length equal to the number of criteria, containing only 1 or -1.")
    }
    if (!is.matrix(bounds) || nrow(bounds) != ncol(matrix) || 
        ncol(bounds) != 2) {
        stop("Bounds must be a matrix with one row per criterion and two columns (min and max).")
    }
    if (any(bounds[, 1] == bounds[, 2])) {
        stop("Bounds for each criterion must have distinct minimum and maximum values.")
    }
    isp <- bounds[cbind(1:ncol(matrix), (types + 1)/2 + 1)]
    norm_distances <- abs((matrix - isp)/(bounds[, 1] - bounds[, 
        2]))
    preference_scores <- rowSums(norm_distances * weights)
    return(preference_scores)
}

apply.REGIME <- function (mat, beneficial.vector, weights, doPreOrder = FALSE) 
{
    weights <- weights/sum(weights)
    X <- as.matrix(mat)
    n <- nrow(X)
    m <- ncol(X)
    g_ind <- matrix(0, n, n)
    all_cols <- seq_len(m)
    non_beneficial <- setdiff(all_cols, beneficial.vector)
    for (i in seq_len(n)) {
        for (k in seq_len(n)) {
            if (i != k) {
                for (j in seq_len(m)) {
                  if (j %in% beneficial.vector) {
                    if (X[i, j] >= X[k, j]) {
                      g_ind[i, k] <- g_ind[i, k] + weights[j]
                    }
                    else {
                      g_ind[i, k] <- g_ind[i, k] - weights[j]
                    }
                  }
                  else {
                    if (X[i, j] < X[k, j]) {
                      g_ind[i, k] <- g_ind[i, k] + weights[j]
                    }
                    else {
                      g_ind[i, k] <- g_ind[i, k] - weights[j]
                    }
                  }
                }
            }
        }
    }
    cp.matrix <- matrix("-", n, n)
    for (i in seq_len(n)) {
        for (k in seq_len(n)) {
            if (i != k) {
                if (g_ind[i, k] > 0) {
                  cp.matrix[i, k] <- "P+"
                }
                if (abs(g_ind[i, k]) < 1e-14 || abs(g_ind[i, 
                  k] - g_ind[k, i]) < 1e-14) {
                  cp.matrix[i, k] <- "I"
                }
            }
        }
    }
    if (isTRUE(doPreOrder)) {
        po.res <- apply.po.ranking(cp.matrix)
        return(list(cp.matrix = cp.matrix, po.result = po.res))
    }
    else {
        return(cp.matrix)
    }
}

apply.COPELAND <- function (mat, beneficial.vector) 
{
    X <- matrix(0, nrow = nrow(mat), ncol = nrow(mat))
    for (i in seq_len(nrow(mat))) {
        for (k in seq_len(nrow(mat))) {
            if (i != k) {
                for (j in seq_len(ncol(mat))) {
                  if (j %in% beneficial.vector) {
                    if (mat[i, j] > mat[k, j]) {
                      X[i, k] <- X[i, k] + 1
                    }
                    else if (mat[i, j] < mat[k, j]) {
                      X[i, k] <- X[i, k] - 1
                    }
                  }
                  else {
                    if (mat[i, j] > mat[k, j]) {
                      X[i, k] <- X[i, k] - 1
                    }
                    else if (mat[i, j] < mat[k, j]) {
                      X[i, k] <- X[i, k] + 1
                    }
                  }
                }
            }
        }
    }
    total <- rowSums(X)
    return(total)
}

apply.SRMP <- function (evaluations.mat, reference.profiles, weights) 
{
    comparisons <- c()
    for (i in 1:nrow(evaluations.mat)) {
        comparisons <- c(comparisons, sum((evaluations.mat[i, 
            ] >= reference.profiles[1, ]) * weights))
    }
    ref.idx <- 2
    while (sum(duplicated(comparisons)) > 0) {
        duplicated_indices <- which(duplicated(comparisons) | 
            duplicated(comparisons, fromLast = TRUE))
        comparisons.2 <- comparisons
        for (i in duplicated_indices) {
            comparisons.2[i] <- sum((evaluations.mat[i, ] >= 
                reference.profiles[ref.idx, ]) * weights)
        }
        comparisons[duplicated_indices] <- comparisons.2[duplicated_indices]
        ref.idx <- ref.idx + 1
    }
    names(comparisons) <- rownames(evaluations.mat)
    return(comparisons)
}

apply.MACBETH <- function (mat, beneficial.vector, weights) 
{
    X <- as.matrix(mat)
    n <- nrow(X)
    m <- ncol(X)
    all_cols <- seq_len(m)
    non_beneficial <- setdiff(all_cols, beneficial.vector)
    best <- numeric(m)
    worst <- numeric(m)
    for (j in seq_len(m)) {
        col_j <- X[, j]
        if (j %in% beneficial.vector) {
            best[j] <- max(col_j)
            worst[j] <- min(col_j)
        }
        else {
            best[j] <- min(col_j)
            worst[j] <- max(col_j)
        }
    }
    eps <- 1e-16
    for (j in seq_len(m)) {
        X[, j] <- (X[, j] - worst[j])/(best[j] - worst[j] + eps)
    }
    X <- X * weights
    V <- rowSums(X)
    return(V)
}

apply.MARCOS <- function (mat, weights, beneficial.vector) 
{
    n <- nrow(mat)
    m <- ncol(mat)
    ideal <- apply(mat, 2, function(x) ifelse(seq_along(x) %in% 
        beneficial.vector, max(x), min(x)))
    anti_ideal <- apply(mat, 2, function(x) ifelse(seq_along(x) %in% 
        beneficial.vector, min(x), max(x)))
    extended_mat <- rbind(mat, ideal, anti_ideal)
    normalized_mat <- matrix(NA, nrow = nrow(extended_mat), ncol = m)
    for (j in 1:m) {
        for (i in 1:nrow(extended_mat)) {
            if (j %in% beneficial.vector) {
                normalized_mat[i, j] <- extended_mat[i, j]/extended_mat[n + 
                  1, j]
            }
            else {
                normalized_mat[i, j] <- extended_mat[n + 1, j]/extended_mat[i, 
                  j]
            }
        }
    }
    weighted_mat <- t(weights * t(normalized_mat))
    S <- rowSums(weighted_mat)
    k_neg <- S/S[n + 2]
    k_pos <- S/S[n + 1]
    f_k_pos <- k_neg[1:n]/(k_pos[1:n] + k_neg[1:n])
    f_k_neg <- k_pos[1:n]/(k_pos[1:n] + k_neg[1:n])
    f_k <- (k_pos[1:n] + k_neg[1:n])/(1 + (1 - f_k_pos)/f_k_pos + 
        (1 - f_k_neg)/f_k_neg)
    return(f_k)
}

apply.CODAS <- function (mat, weights, beneficial.vector, psi) 
{
    max.min.vector <- c()
    for (col in 1:ncol(mat)) {
        if (col %in% beneficial.vector) {
            max.min.vector <- c(max.min.vector, max(mat[, col]))
        }
        else {
            max.min.vector <- c(max.min.vector, min(mat[, col]))
        }
    }
    normalized.mat.beneficial <- t(t(mat[, beneficial.vector])/max.min.vector[beneficial.vector])
    normalized.mat.non.beneficial <- t(max.min.vector[-beneficial.vector]/t(mat[, 
        -beneficial.vector]))
    normalized.mat <- matrix(NA, nrow = nrow(mat), ncol = ncol(mat))
    rownames(normalized.mat) <- rownames(mat)
    colnames(normalized.mat) <- colnames(mat)
    normalized.mat[, beneficial.vector] <- normalized.mat.beneficial
    normalized.mat[, -beneficial.vector] <- normalized.mat.non.beneficial
    weighted.normalized.mat <- t(weights * t(normalized.mat))
    negative.ideal <- apply(weighted.normalized.mat, 2, min)
    E_i <- sqrt(rowSums((sweep(weighted.normalized.mat, 2, negative.ideal, 
        FUN = "-"))^2))
    T_i <- rowSums(abs(sweep(weighted.normalized.mat, 2, negative.ideal, 
        FUN = "-")))
    h_ik <- matrix(NA, nrow = length(E_i), ncol = length(E_i))
    for (i in 1:length(E_i)) {
        for (k in 1:length(E_i)) {
            h_ik[i, k] <- E_i[i] - E_i[k] + (psi * (E_i[i] - 
                E_i[k]) * (T_i[i] - T_i[k]))
        }
    }
    assessment.score <- rowSums(h_ik)
    return(assessment.score)
}

apply.SECA <- function (mat, beneficial.vector, beta = 3) 
{
    X <- mat
    for (j in seq_len(ncol(mat))) {
        if (j %in% beneficial.vector) {
            X[, j] <- min(X[, j])/X[, j]
        }
        else {
            X[, j] <- X[, j]/max(X[, j])
        }
    }
    std <- apply(X, 2, function(x) sqrt(sum((x - mean(x))^2)/(nrow(X) - 
        1)))
    std <- std/sum(std)
    sim.mat <- 1 - cor(X)
    sim.mat <- rowSums(sim.mat)/sum(rowSums(sim.mat))
    target_function <- function(variables) {
        Lmb_a <- min(rowSums(X * variables))
        Lmb_b <- sum((variables - std)^2)
        Lmb_c <- sum((variables - sim.mat)^2)
        Lmb <- Lmb_a - beta * (Lmb_b + Lmb_c)
        return(-Lmb)
    }
    gradient_function <- function(variables) {
        grad <- numeric(length(variables))
        for (k in seq_along(variables)) {
            perturbed <- variables
            epsilon <- 1e-08
            perturbed[k] <- variables[k] + epsilon
            grad[k] <- (target_function(perturbed) - target_function(variables))/epsilon
        }
        return(grad)
    }
    constraint_function <- function(variables) {
        return(sum(variables) - 1)
    }
    constraint_gradient <- function(variables) {
        return(rep(1, length(variables)))
    }
    N <- ncol(mat)
    start_vals <- runif(N, 0.001, 1)
    start_vals <- start_vals/sum(start_vals)
    result <- nloptr::nloptr(x0 = start_vals, eval_f = target_function, 
        eval_grad_f = gradient_function, lb = rep(1e-04, N), 
        ub = rep(1, N), eval_g_eq = constraint_function, eval_jac_g_eq = constraint_gradient, 
        opts = list(algorithm = "NLOPT_LD_SLSQP", xtol_rel = 1e-08))
    return(result$solution)
}

apply.DEMATEL <- function (comparisons.mat) 
{
    X <- comparisons.mat/max(rowSums(comparisons.mat))
    D <- rowSums(X %*% matlib::inv(diag(dim(X)[1]) - X))
    R <- colSums(X %*% matlib::inv(diag(dim(X)[1]) - X))
    D.minus.R <- D - R
    D.plus.R <- D + R
    return(list(D.minus.R, D.plus.R))
}

apply.ELECTRE1 <- function (mat, weights) 
{
    norm.mat <- t(t(mat/sqrt(colSums(mat^2))) * weights)
    concordance.mat <- matrix(NA, nrow = nrow(norm.mat), ncol = nrow(norm.mat))
    for (i in 1:nrow(norm.mat)) {
        for (j in 1:nrow(norm.mat)) {
            concordance.mat[i, j] <- sum(weights[norm.mat[i, 
                ] > norm.mat[j, ]])
        }
    }
    C.bar <- sum(colSums(concordance.mat))/(length(concordance.mat) - 
        sqrt(length(concordance.mat)))
    discordance.mat <- matrix(NA, nrow = nrow(norm.mat), ncol = nrow(norm.mat))
    for (i in 1:nrow(norm.mat)) {
        for (j in 1:nrow(norm.mat)) {
            if (i == j) {
                discordance.mat[i, j] <- 0
            }
            else {
                discordance.mat[i, j] <- abs(min(norm.mat[i, 
                  ] - norm.mat[j, ]))/max(abs(norm.mat[i, ] - 
                  norm.mat[j, ]))
            }
        }
    }
    D.bar <- sum(colSums(discordance.mat))/(length(discordance.mat) - 
        sqrt(length(discordance.mat)))
    concordance.mat > C.bar & discordance.mat > D.bar
    return(list((concordance.mat > C.bar & discordance.mat > 
        D.bar), concordance.mat, discordance.mat))
}

apply.OCRA <- function (mat, weights, beneficial.vector) 
{
    if (!is.matrix(mat)) {
        stop("'mat' must be a matrix.")
    }
    if (length(weights) != ncol(mat)) {
        stop("Length of 'weights' must match the number of columns in 'mat'.")
    }
    if (abs(sum(weights) - 1) > 1e-09) {
        stop("The sum of 'weights' must be 1.")
    }
    ocra_normalization <- function(x, cost = FALSE) {
        if (cost) {
            return((max(x) - x)/min(x))
        }
        else {
            return((x - min(x))/min(x))
        }
    }
    n <- nrow(mat)
    m <- ncol(mat)
    I <- rep(0, n)
    O <- rep(0, n)
    for (j in seq_len(m)) {
        if (j %in% beneficial.vector) {
            O <- O + weights[j] * ocra_normalization(mat[, j], 
                cost = FALSE)
        }
        else {
            I <- I + weights[j] * ocra_normalization(mat[, j], 
                cost = TRUE)
        }
    }
    I <- I - min(I)
    O <- O - min(O)
    total <- I + O
    pref_values <- total - min(total)
    return(pref_values)
}

apply.ROV <- function (mat, weights, beneficial.vector) 
{
    X <- mat
    weights <- weights/sum(weights)
    for (j in seq_len(ncol(mat))) {
        D <- max(X[, j]) - min(X[, j])
        if (D == 0) 
            D <- 1
        if (j %in% beneficial.vector) {
            X[, j] <- (X[, j] - min(X[, j]))/D
        }
        else {
            X[, j] <- (max(X[, j]) - X[, j])/D
        }
    }
    u <- rowSums(X * weights)
    return(u)
}

apply.TOPSIS <- function (A, w) 
{
    if (length(w) != ncol(A)) {
        stop("The dimensions of the weight vector and matrix do not match. Unable to proceed.")
    }
    normalized.A <- t(t(A)/sqrt(colSums(A^2)))
    normalized.A <- normalized.A * w
    S.pos <- sqrt(rowSums((t(t(normalized.A) - apply(normalized.A, 
        2, max)))^2))
    S.neg <- sqrt(rowSums((t(t(normalized.A) - apply(normalized.A, 
        2, min)))^2))
    performance.score <- S.neg/(S.pos + S.neg)
    return(performance.score)
}

apply.SMART <- function (dataset, grades, lower, upper, beneficial.vector) 
{
    X <- as.matrix(dataset)
    w <- grades
    for (i in seq_along(w)) {
        w[i] <- (sqrt(2))^w[i]
    }
    w <- w/sum(w)
    n_alt <- nrow(X)
    n_crit <- ncol(X)
    for (i in seq_len(n_crit)) {
        denom <- upper[i] - lower[i]
        if (denom <= 0) {
            stop(sprintf("Invalid bounds for criterion %d: upper <= lower.", 
                i))
        }
        frac_vec <- (X[, i] - lower[i])/denom * 64
        if (i %in% beneficial.vector) {
            X[, i] <- 4 + log2(frac_vec)
        }
        else {
            X[, i] <- 10 - log2(frac_vec)
        }
    }
    S <- sweep(X, 2, w, FUN = "*")
    Y <- rowSums(S)
    result <- cbind(index = seq_len(n_alt), score = Y)
    return(result)
}

apply.TODIM <- function (mat, weights, beneficial.vector, teta = 1) 
{
    X <- as.matrix(mat)
    n <- nrow(X)
    m <- ncol(X)
    for (j in beneficial.vector) {
        X[, j] <- X[, j]/sum(X[, j])
    }
    non.beneficial <- setdiff(seq_len(m), beneficial.vector)
    for (j in non.beneficial) {
        X[, j] <- (1/X[, j])/sum(1/X[, j])
    }
    weights <- weights/max(weights)
    sumW <- sum(weights)
    D <- matrix(0, n, n)
    for (i in seq_len(n)) {
        for (j in seq_len(n)) {
            if (i != j) {
                for (k in seq_len(m)) {
                  p_i <- X[i, k]
                  p_j <- X[j, k]
                  diff <- p_i - p_j
                  if (diff > 0) {
                    D[i, j] <- D[i, j] + ((weights[k] * diff)/sumW)^0.5
                  }
                  else if (abs(diff) < .Machine$double.eps) {
                    D[i, j] <- D[i, j] + 0
                  }
                  else {
                    D[i, j] <- D[i, j] + (-1/teta) * (sumW * 
                      ((p_j - p_i)/weights[k]))^0.5
                  }
                }
            }
        }
    }
    r <- rowSums(D)
    min_r <- min(r)
    max_r <- max(r)
    if (abs(max_r - min_r) < .Machine$double.eps) {
        r <- rep(1, length(r))
    }
    else {
        r <- (r - min_r)/(max_r - min_r)
    }
    return(r)
}

apply.PIV <- function (mat, weights, beneficial.vector) 
{
    X <- mat
    for (j in seq_len(ncol(mat))) {
        X[, j] <- (X[, j]/sqrt(sum(X[, j]^2))) * weights[j]
    }
    for (j in seq_len(ncol(mat))) {
        if (j %in% beneficial.vector) {
            X[, j] <- max(X[, j]) - X[, j]
        }
        else {
            X[, j] <- X[, j] - min(X[, j])
        }
    }
    D <- rowSums(X)
    return(D)
}

apply.ARAS <- function (mat, weights, beneficial.vector) 
{
    min.vector <- apply(mat, 2, min)
    max.vector <- apply(mat, 2, max)
    optimal.value <- c()
    for (i in 1:ncol(mat)) {
        if (i %in% beneficial.vector) {
            optimal.value <- c(optimal.value, max.vector[i])
        }
        else {
            optimal.value <- c(optimal.value, min.vector[i])
        }
    }
    edited.mat <- matrix(NA, nrow = nrow(mat) + 1, ncol = ncol(mat))
    for (i in 1:(nrow(mat) + 1)) {
        for (j in 1:ncol(mat)) {
            if (j %in% beneficial.vector) {
                if (i == 1) {
                  edited.mat[i, j] <- optimal.value[j]/(sum(mat[, 
                    j]) + optimal.value[j])
                }
                else {
                  edited.mat[i, j] <- mat[i - 1, j]/(sum(mat[, 
                    j]) + optimal.value[j])
                }
            }
            else {
                if (i == 1) {
                  edited.mat[i, j] <- 1/optimal.value[j]
                }
                else {
                  edited.mat[i, j] <- 1/mat[i - 1, j]
                }
            }
        }
    }
    edited.mat[, -beneficial.vector] <- t(t(edited.mat[, -beneficial.vector])/colSums(edited.mat[, 
        -beneficial.vector]))
    edited.mat <- edited.mat * weights
    Si <- rowSums(edited.mat)
    S0 <- Si[1]
    Ki <- Si/S0
    return(Ki)
}

apply.MAIRCA <- function (mat, weights, types) 
{
    if (!is.matrix(mat)) {
        stop("'mat' must be a matrix.")
    }
    if (length(weights) != ncol(mat)) {
        stop("Length of 'weights' must match the number of columns in 'mat'.")
    }
    if (length(types) != ncol(mat)) {
        stop("Length of 'types' must match the number of columns in 'mat'.")
    }
    if (abs(sum(weights) - 1) > 1e-09) {
        stop("The sum of 'weights' must be 1.")
    }
    if (!all(types %in% c(1, -1))) {
        stop("'types' must contain only 1 (profit) or -1 (cost).")
    }
    n <- nrow(mat)
    Tp <- (1/n) * weights
    normalized_mat <- matrix(NA, nrow = n, ncol = ncol(mat))
    for (j in seq_len(ncol(mat))) {
        min_val <- min(mat[, j])
        max_val <- max(mat[, j])
        if (types[j] == 1) {
            normalized_mat[, j] <- (mat[, j] - min_val)/(max_val - 
                min_val)
        }
        else {
            normalized_mat[, j] <- (max_val - mat[, j])/(max_val - 
                min_val)
        }
    }
    Tr <- -sweep(normalized_mat, 2, Tp, FUN = "*")
    G <- sweep(Tr, 2, Tp, FUN = "-")
    pref_values <- rowSums(G)
    return(pref_values)
}

apply.MULTIMOORA <- function (mat, beneficial.vector) 
{
    normalized_data <- sweep(mat, 2, sqrt(colSums(mat^2)), "/")
    all_criteria <- seq_len(ncol(mat))
    non_beneficial.vector <- setdiff(all_criteria, beneficial.vector)
    s_plus <- if (length(beneficial.vector) > 0) {
        rowSums(normalized_data[, beneficial.vector, drop = FALSE])
    }
    else {
        rep(0, nrow(mat))
    }
    s_minus <- if (length(non_beneficial.vector) > 0) {
        rowSums(normalized_data[, non_beneficial.vector, drop = FALSE])
    }
    else {
        rep(0, nrow(mat))
    }
    moora_scores <- s_plus - s_minus
    best_values <- sapply(all_criteria, function(i) {
        if (i %in% beneficial.vector) {
            max(normalized_data[, i])
        }
        else {
            min(normalized_data[, i])
        }
    })
    moora_rp_scores <- apply(abs(sweep(normalized_data, 2, best_values, 
        "-")), 1, max)
    multi_scores <- mat[, 1]
    for (i in seq_len(ncol(mat))) {
        if (i %in% beneficial.vector) {
            multi_scores <- multi_scores * mat[, i]
        }
        else {
            multi_scores <- multi_scores/mat[, i]
        }
    }
    moora_scores <- moora_scores/max(moora_scores)
    moora_rp_scores <- moora_rp_scores/max(moora_rp_scores)
    multi_scores <- multi_scores/max(multi_scores)
    rankings_1 <- cbind(1:nrow(mat), moora_scores)
    rankings_2 <- cbind(1:nrow(mat), moora_rp_scores)
    rankings_3 <- cbind(1:nrow(mat), multi_scores)
    list(MOORA = rankings_1, MOORA_RP = rankings_2, MULTIMOORA = rankings_3)
}

apply.ORESTE <- function (mat, weights, beneficial.vector, alpha = 0.4) 
{
    if (ncol(mat) != length(weights)) {
        stop("Number of weights must match the number of columns in 'mat'.")
    }
    n_alts <- nrow(mat)
    n_crit <- ncol(mat)
    criterion_type <- rep("min", n_crit)
    criterion_type[beneficial.vector] <- "max"
    X <- matrix(as.numeric(mat), nrow = n_alts, ncol = n_crit)
    w <- rank(-weights, ties.method = "min")
    for (j in seq_len(n_crit)) {
        if (criterion_type[j] == "max") {
            X[, j] <- rank(-X[, j], ties.method = "min")
        }
        else {
            X[, j] <- rank(X[, j], ties.method = "min")
        }
    }
    r_ind <- matrix(0, nrow = n_alts, ncol = n_crit)
    for (i in seq_len(n_alts)) {
        for (j in seq_len(n_crit)) {
            r_ind[i, j] <- alpha * X[i, j] + (1 - alpha) * w[j]
        }
    }
    r_ind_flat <- as.vector(r_ind)
    ranked <- rank(r_ind_flat, ties.method = "min")
    ranked_mat <- matrix(ranked, nrow = n_alts, ncol = n_crit, 
        byrow = FALSE)
    total <- rowSums(ranked_mat)
    return(total)
}

apply.IDOCRIW <- function (mat, beneficial.vector) 
{
    normalized_matrix <- sweep(mat, 2, colSums(mat), "/")
    entropy_values <- rep(0, ncol(normalized_matrix))
    for (col_idx in seq_len(ncol(normalized_matrix))) {
        adjusted_column <- ifelse(normalized_matrix[, col_idx] == 
            0, 1e-09, normalized_matrix[, col_idx])
        entropy_values[col_idx] <- -sum(adjusted_column * log(adjusted_column))/log(ncol(normalized_matrix))
    }
    diversity_index <- 1 - entropy_values
    initial_weights <- diversity_index/sum(diversity_index)
    adjusted_matrix <- mat
    non_beneficial_indices <- setdiff(seq_len(ncol(mat)), beneficial.vector)
    for (col_idx in non_beneficial_indices) {
        adjusted_matrix[, col_idx] <- min(mat[, col_idx])/adjusted_matrix[, 
            col_idx]
    }
    adjusted_matrix <- sweep(adjusted_matrix, 2, colSums(adjusted_matrix), 
        "/")
    max_values <- apply(adjusted_matrix, 2, max)
    priority_matrix <- diag(max_values)
    for (row_idx in seq_along(max_values)) {
        max_row <- which(adjusted_matrix[, row_idx] == max_values[row_idx])[1]
        priority_matrix[row_idx, ] <- adjusted_matrix[max_row, 
            ]
    }
    max_priority <- apply(priority_matrix, 2, max)
    adjustment_matrix <- priority_matrix
    for (col_idx in seq_len(ncol(adjustment_matrix))) {
        adjustment_matrix[, col_idx] <- (-adjustment_matrix[, 
            col_idx] + max_priority[col_idx])/max_values[col_idx]
    }
    diag(adjustment_matrix) <- -colSums(adjustment_matrix)
    optimization_target <- function(weight_vector) {
        weighted_priority <- adjustment_matrix
        for (row_idx in seq_len(nrow(weighted_priority))) {
            for (col_idx in seq_len(ncol(weighted_priority))) {
                if (weighted_priority[row_idx, col_idx] != 0) {
                  weighted_priority[row_idx, col_idx] <- weighted_priority[row_idx, 
                    col_idx] * weight_vector[col_idx]
                }
            }
        }
        return(sum(abs(rowSums(weighted_priority))))
    }
    initial_variables <- rep(1, ncol(adjustment_matrix))
    optimization_result <- optim(par = initial_variables, fn = optimization_target, 
        method = "L-BFGS-B", lower = rep(1e-07, length(initial_variables)), 
        upper = rep(1, length(initial_variables)))
    final_weights <- optimization_result$par * initial_weights
    final_weights <- final_weights/sum(final_weights)
    return(final_weights)
}

apply.CRADIS <- function (mat, weights, beneficial.vector) 
{
    if (length(weights) != ncol(mat)) {
        stop("Unable to proceed. Number of weights must match the number of criteria (columns) in the matrix.")
    }
    if (any(beneficial.vector < 1 | beneficial.vector > ncol(mat))) {
        stop("Unable to proceed. beneficial.vector must contain column numbers within the range of the matrix.")
    }
    normalized.mat <- matrix(NA, nrow = nrow(mat), ncol = ncol(mat))
    min.vector <- apply(mat, 2, min)
    max.vector <- apply(mat, 2, max)
    for (i in 1:nrow(mat)) {
        for (j in 1:ncol(mat)) {
            if (j %in% beneficial.vector) {
                normalized.mat[i, j] <- (mat[i, j] - min.vector[j])/(max.vector[j] - 
                  min.vector[j])
            }
            else {
                normalized.mat[i, j] <- (max.vector[j] - mat[i, 
                  j])/(max.vector[j] - min.vector[j])
            }
        }
    }
    weighted.mat <- t(weights * t(normalized.mat))
    ideal.solution <- apply(weighted.mat, 2, max)
    anti.ideal.solution <- apply(weighted.mat, 2, min)
    Sp <- rowSums(matrix(rep(ideal.solution, each = nrow(weighted.mat)), 
        nrow = nrow(weighted.mat)) - weighted.mat)
    Sm <- rowSums(weighted.mat - matrix(rep(anti.ideal.solution, 
        each = nrow(weighted.mat)), nrow = nrow(weighted.mat)))
    Sop <- sum(ideal.solution - apply(weighted.mat, 2, max))
    Som <- sum(apply(weighted.mat, 2, max) - apply(weighted.mat, 
        2, min))
    Kp <- Sop/Sp
    Km <- Sm/Som
    preference.values <- (Kp + Km)/2
    return(preference.values)
}

apply.entropy <- function (A) 
{
    normalized.A <- t(t(A)/colSums(A))
    e <- 1 - (-1/log(nrow(A)) * colSums(normalized.A * log(normalized.A)))
    entropy <- e/sum(e)
    return(entropy)
}

apply.WSM_WPM <- function (mat, beneficial.vector, weights, method = "WSM") 
{
    if (!(method %in% c("WSM", "WPM"))) {
        stop("Error, unable to proceed, please provide a valid method. Options include 'WSM' or 'WPM'.")
    }
    norm.WSM <- function(matrix, beneficial.vector) {
        m <- nrow(matrix)
        n <- ncol(matrix)
        result_matrix <- matrix(0, nrow = m, ncol = n)
        for (j in 1:n) {
            if (j %in% beneficial.vector) {
                X_max <- max(matrix[, j])
                denominator <- sum(X_max - matrix[, j])
                result_matrix[, j] <- 1 - (X_max - matrix[, j])/denominator
            }
            else {
                X_min <- min(matrix[, j])
                denominator <- sum(matrix[, j] - X_min)
                result_matrix[, j] <- 1 - (matrix[, j] - X_min)/denominator
            }
        }
        return(result_matrix)
    }
    result <- norm.WSM(mat, beneficial.vector)
    if (method == "WSM") {
        preference.scores <- rowSums(t(weights * t(norm.WSM(mat, 
            beneficial.vector))))
    }
    else {
        preference.scores <- rowProds(t(t(norm.WSM(mat, beneficial.vector))^weights))
    }
    return(preference.scores)
}

