apply.MAUT <- function (mat, weights, beneficial.vector, utility.functions, 
    step.size = 1) 
{
    X <- as.matrix(mat)
    for (j in seq_len(ncol(X))) {
        if (j %in% beneficial.vector) {
            X[, j] <- (X[, j] - min(X[, j]))/(max(X[, j]) - min(X[, 
                j]) + 1e-15)
        }
        else {
            X[, j] <- 1 + (min(X[, j]) - X[, j])/(max(X[, j]) - 
                min(X[, j]) + 1e-15)
        }
    }
    u.exp <- function(x) (exp(x^2) - 1)/1.72
    u.step <- function(x, op) ceiling(op * x)/op
    u.log <- function(x) log10(9 * x + 1)
    u.ln <- function(x) log((exp(1) - 1) * x + 1)
    u.quad <- function(x) (2 * x - 1)^2
    for (i in seq_len(ncol(X))) {
        if (utility.functions[i] == "exp") {
            X[, i] <- sapply(X[, i], u.exp)
        }
        else if (utility.functions[i] == "step") {
            X[, i] <- sapply(X[, i], u.step, op = step.size)
        }
        else if (utility.functions[i] == "quad") {
            X[, i] <- sapply(X[, i], u.quad)
        }
        else if (utility.functions[i] == "log") {
            X[, i] <- sapply(X[, i], u.log)
        }
        else if (utility.functions[i] == "ln") {
            X[, i] <- sapply(X[, i], u.ln)
        }
    }
    for (i in seq_len(ncol(X))) {
        X[, i] <- X[, i] * weights[i]
    }
    Y <- rowSums(X)
    result <- cbind(1:length(Y), Y)
    colnames(result) <- c("Alternative", "Score")
    return(result)
}

apply.PSI <- function (mat, beneficial.vector) 
{
    X <- mat
    for (j in seq_len(ncol(mat))) {
        if (j %in% beneficial.vector) {
            X[, j] <- X[, j]/max(X[, j])
        }
        else {
            X[, j] <- min(X[, j])/X[, j]
        }
    }
    R <- colMeans(X)
    Z <- (X - matrix(R, nrow = nrow(X), ncol = ncol(X), byrow = TRUE))^2
    PV <- colSums(Z)
    T <- 1 - PV
    P <- T/sum(T)
    I <- rowSums(X * matrix(P, nrow = nrow(X), ncol = ncol(X), 
        byrow = TRUE))
    return(I)
}

apply.RIM <- function (mat, weights, AB, CD) 
{
    if (!is.matrix(mat)) {
        stop("'mat' must be a matrix with the values of the alternatives.")
    }
    if (missing(weights)) {
        stop("A vector containing n weights (summing up to 1) should be provided.")
    }
    if (abs(sum(weights) - 1) > 1e-09) {
        stop("The sum of 'weights' is not equal to 1.")
    }
    if (length(weights) != ncol(mat)) {
        stop("Length of 'weights' does not match the number of criteria.")
    }
    if (!is.matrix(AB) || ncol(AB) != ncol(mat)) {
        stop("Dimensions of 'AB' do not match the number of criteria.")
    }
    if (!is.matrix(CD) || ncol(CD) != ncol(mat)) {
        stop("Dimensions of 'CD' do not match the number of criteria.")
    }
    N <- matrix(nrow = nrow(mat), ncol = ncol(mat))
    for (j in seq_len(ncol(mat))) {
        A <- AB[1, j]
        B <- AB[2, j]
        C_ <- CD[1, j]
        D_ <- CD[2, j]
        for (i in seq_len(nrow(mat))) {
            x <- mat[i, j]
            if (x < A || x > B) {
                warning(paste0("Value x = ", x, " is outside [A, B] = [", 
                  A, ", ", B, "] for row i=", i, ", column j=", 
                  j, ". Setting N=0."))
                N[i, j] <- 0
                next
            }
            if (x >= C_ && x <= D_) {
                N[i, j] <- 1
            }
            else if (x >= A && x <= C_) {
                denom <- abs(A - C_)
                if (denom < 1e-15) {
                  if (abs(x - A) < 1e-15) {
                    N[i, j] <- 1
                  }
                  else {
                    N[i, j] <- 0
                    warning(sprintf("Degenerate interval [A,C] (A=%g, C=%g) at col j=%d. ", 
                      A, C_, j), "Setting N=0 for row=", i)
                  }
                }
                else {
                  N[i, j] <- 1 - (min(abs(x - C_), abs(x - D_))/denom)
                }
            }
            else if (x >= D_ && x <= B) {
                denom <- abs(D_ - B)
                if (denom < 1e-15) {
                  if (abs(x - B) < 1e-15) {
                    N[i, j] <- 1
                  }
                  else {
                    N[i, j] <- 0
                    warning(sprintf("Degenerate interval [D,B] (D=%g, B=%g) at col j=%d. ", 
                      D_, B, j), "Setting N=0 for row=", i)
                  }
                }
                else {
                  N[i, j] <- 1 - (min(abs(x - C_), abs(x - D_))/denom)
                }
            }
            else {
                N[i, j] <- 0
                warning(paste0("Value x = ", x, " does not fall into [A,C], [C,D], or [D,B]. ", 
                  "Setting N=0 for row i=", i, ", column j=", 
                  j))
            }
        }
    }
    W <- diag(weights)
    NW <- N %*% W
    pos.Dis <- numeric(nrow(mat))
    neg.Dis <- numeric(nrow(mat))
    for (i in seq_len(nrow(mat))) {
        pos.Dis[i] <- sqrt(sum((NW[i, ] - weights)^2))
        neg.Dis[i] <- sqrt(sum(NW[i, ]^2))
    }
    R <- neg.Dis/(neg.Dis + pos.Dis)
    return(data.frame(Alternatives = seq_len(nrow(mat)), R = R, 
        Ranking = rank(-R, ties.method = "first")))
}

apply.GRA <- function (mat, weights, beneficial.vector, epsilon = 0.5) 
{
    normalized.mat <- matrix(0, nrow = nrow(mat), ncol = ncol(mat))
    for (j in seq_len(ncol(mat))) {
        if (j %in% beneficial.vector) {
            normalized.mat[, j] <- (mat[, j] - min(mat[, j]))/(max(mat[, 
                j]) - min(mat[, j]) + 1e-10)
        }
        else {
            normalized.mat[, j] <- (max(mat[, j]) - mat[, j])/(max(mat[, 
                j]) - min(mat[, j]) + 1e-10)
        }
    }
    deviation.sequence <- 1 - normalized.mat
    gra.coefficient <- epsilon/(deviation.sequence + epsilon)
    gra.scores <- rowSums(gra.coefficient * weights)/nrow(mat)
    return(gra.scores)
}

apply.PROMETHEE <- function (A, weights, type = "II") 
{
    colMaxs <- apply(A, 2, function(x) max(x, na.rm = TRUE))
    colMins <- apply(A, 2, function(x) min(x, na.rm = TRUE))
    processed.A <- t(apply(A, 1, function(row) {
        (row - colMins)/(colMaxs - colMins)
    }))
    pairwise.diff.all <- function(mat.data) {
        n <- nrow(mat.data)
        result <- list()
        for (i in 1:n) {
            for (j in 1:n) {
                if (i != j) {
                  diff <- mat.data[i, ] - mat.data[j, ]
                  result[[paste("D(M", i, "-M", j, ")", sep = "")]] <- diff
                }
            }
        }
        return(do.call(rbind, result))
    }
    pairwise.diffs <- pairwise.diff.all(processed.A)
    pairwise.diffs[pairwise.diffs < 0] <- 0
    processed.A <- sweep(pairwise.diffs, 2, weights, `*`)
    pairwise.vector <- rowSums(processed.A)/sum(weights)
    row.names <- unique(unlist(lapply(names(pairwise.vector), 
        function(x) strsplit(x, "-")[[1]])))
    row.names <- gsub("D\\(|\\)", "", row.names)
    n <- length(row.names)
    preference.matrix <- matrix(NA, nrow = n, ncol = n, dimnames = list(row.names, 
        row.names))
    for (pair in names(pairwise.vector)) {
        elements <- unlist(strsplit(gsub("D\\(|\\)", "", pair), 
            "-"))
        row_name <- elements[1]
        col_name <- elements[2]
        preference.matrix[row_name, col_name] <- pairwise.vector[pair]
    }
    diag(preference.matrix) <- "-"
    preference.matrix <- preference.matrix[1:nrow(A), 1:ncol(A)]
    preference.matrix[preference.matrix == "-"] <- NA
    numeric.matrix <- matrix(as.numeric(preference.matrix), nrow = nrow(preference.matrix), 
        ncol = ncol(preference.matrix))
    if (type == "II") {
        leaving.flow <- rowMeans(numeric.matrix, na.rm = TRUE)
        entering.flow <- colMeans(numeric.matrix, na.rm = TRUE)
        net.out.ranking <- leaving.flow - entering.flow
        return(list(leaving.flow, entering.flow, net.out.ranking, 
            order(net.out.ranking)))
    }
    else if (type == "I") {
        leaving.flow <- rowSums(numeric.matrix, na.rm = TRUE)
        entering.flow <- colSums(numeric.matrix, na.rm = TRUE)
        net.out.ranking <- leaving.flow - entering.flow
        return(list(leaving.flow, entering.flow, net.out.ranking))
    }
    else {
        stop("Inavlid type. Unable to proceed. Input should be either type I or type II.")
    }
}

apply.MABAC <- function (mat, weights, types) 
{
    if (!is.matrix(mat)) {
        stop("'mat' must be a matrix.")
    }
    if (length(weights) != ncol(mat)) {
        stop("Length of 'weights' must match the number of columns in 'mat'.")
    }
    if (length(types) != ncol(mat)) {
        stop("Length of 'types' must match the number of columns in 'mat'.")
    }
    if (abs(sum(weights) - 1) > 1e-09) {
        stop("The sum of 'weights' must be 1.")
    }
    if (!all(types %in% c(1, -1))) {
        stop("'types' must contain only 1 (profit) or -1 (cost).")
    }
    n <- nrow(mat)
    normalized_mat <- matrix(NA, nrow = n, ncol = ncol(mat))
    for (j in seq_len(ncol(mat))) {
        col_j <- mat[, j]
        min_val <- min(col_j)
        max_val <- max(col_j)
        if (types[j] == 1) {
            normalized_mat[, j] <- (col_j - min_val)/(max_val - 
                min_val)
        }
        else {
            normalized_mat[, j] <- (max_val - col_j)/(max_val - 
                min_val)
        }
    }
    weighted_mat <- sweep((normalized_mat + 1), 2, weights, FUN = "*")
    product_by_column <- apply(weighted_mat, 2, prod)
    G <- product_by_column^(1/n)
    Q <- sweep(weighted_mat, 2, G, FUN = "-")
    pref_values <- rowSums(Q)
    return(pref_values)
}

apply.COCOSO <- function (mat, weights, beneficial.vector) 
{
    min.vector <- apply(mat, 2, min)
    max.vector <- apply(mat, 2, max)
    t(t(mat - min.vector)/(max.vector - min.vector))
    normalized.mat <- matrix(NA, nrow = nrow(mat), ncol = ncol(mat))
    for (i in 1:nrow(mat)) {
        for (j in 1:ncol(mat)) {
            if (j %in% beneficial.vector) {
                normalized.mat[i, j] <- (mat[i, j] - min.vector[j])/(max.vector[j] - 
                  min.vector[j])
            }
            else {
                normalized.mat[i, j] <- (max.vector[j] - mat[i, 
                  j])/(max.vector[j] - min.vector[j])
            }
        }
    }
    weighted.normalized.mat <- t(weights * t(normalized.mat))
    powered.mat <- t(t(normalized.mat)^weights)
    S_i <- rowSums(weighted.normalized.mat)
    P_i <- rowSums(powered.mat)
    K.a <- (P_i + S_i)/sum(P_i + S_i)
    K.b <- S_i/min(S_i) + P_i/min(P_i)
    K.c <- ((0.5 * S_i) + (0.5 * P_i))/((0.5 * max(S_i)) + (0.5 * 
        max(P_i)))
    aggregated.appraisal.scores <- (K.a * K.b * K.c)^1/3 + 1/3 * 
        (K.a + K.b + K.c)
    return(aggregated.appraisal.scores)
}

apply.SAW <- function (mat, weights, beneficial.vector) 
{
    maxOrMinMatrix <- function(mat, weights, beneficial.vector) {
        if (!is.matrix(mat)) {
            stop("'mat' must be a matrix.")
        }
        results <- sapply(seq_len(ncol(mat)), function(col_idx) {
            column_data <- mat[, col_idx]
            if (col_idx %in% beneficial.vector) {
                max(column_data, na.rm = TRUE)
            }
            else {
                min(column_data, na.rm = TRUE)
            }
        })
        if (!is.null(colnames(mat))) {
            names(results) <- colnames(mat)
        }
        return(results)
    }
    hold.vals <- maxOrMinMatrix(mat, weights, beneficial.vector)
    edited.mat <- mat
    for (i in 1:nrow(edited.mat)) {
        for (j in 1:ncol(edited.mat)) {
            if (j %in% beneficial.vector) {
                edited.mat[i, j] <- edited.mat[i, j]/hold.vals[j]
            }
            else {
                edited.mat[i, j] <- hold.vals[j]/edited.mat[i, 
                  j]
            }
        }
    }
    A.i <- (edited.mat) %*% weights
    ranking <- nrow(mat) - rank(A.i) + 1
    return(list(A.i, ranking))
}
